// usage: node cells.mjs build.nbt x0 x1 y z0 z1  -> prints block per cell (y fixed)
import { load } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const [file, x0, x1, y, z0, z1] = process.argv.slice(2);
const g = load(file);
for (let z = +z0; z <= +z1; z++) {
  const row = [];
  for (let x = +x0; x <= +x1; x++) {
