      ...win(N(21), 4, 5, GU), ...win(N(21), 10, 11, GU), [8, 2, 21, 8, 3, 21],
      [2, 1, 17, 2, 3, 17], [13, 1, 17, 13, 3, 17],
    ] });
  // attic floor y9 with the ladder hole at (11,9,17)
  g.fill([5, 9, 15], [11, 9, 19], "dark_oak_planks");
  g.fill([11, 9, 17], [11, 9, 17], "air");
