    y: 5, ridgeAxis: "x", pitch: 2, upperPitch: "half", lower: 2, material: "deepslate_tiles", verge: "dark_oak_planks", overhang: { north: 0, south: 1, east: 1, west: 1 },
    steep: true, dormers: { face: "north", style: "shed", width: 7, count: 1 },
